if !(IsFeatureImplemented(FEAT_DPB2) && IsFeatureImplemented(FEAT_MTE)) then
    Undefined();
elsif EffectivelyAtEL0NotInHost() then
    if !AArch64_CanTrapDC(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
        ExecuteAsNOP();
    elsif SCTLR_EL1().UCI == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EL2Enabled() && HCR_EL2().TPCP == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_FGT) && (!HaveEL(EL3) || SCR_EL3().FGTEn == '1') && HFGITR_EL2().DCCVADP == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        if AArch64_TreatDCAsNOP(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
            ExecuteAsNOP();
        else
            AArch64_DC(X{64}(t), CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP);
        end;
    end;
elsif EffectivelyAtEL0InHost() then
    if !AArch64_CanTrapDC(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
        ExecuteAsNOP();
    elsif SCTLR_EL2().UCI == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        if AArch64_TreatDCAsNOP(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
            ExecuteAsNOP();
        else
            AArch64_DC(X{64}(t), CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP);
        end;
    end;
elsif PSTATE.EL == EL1 then
    if !AArch64_CanTrapDC(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
        ExecuteAsNOP();
    elsif EL2Enabled() && HCR_EL2().TPCP == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_FGT) && (!HaveEL(EL3) || SCR_EL3().FGTEn == '1') && HFGITR_EL2().DCCVADP == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        if AArch64_TreatDCAsNOP(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
            ExecuteAsNOP();
        else
            AArch64_DC(X{64}(t), CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP);
        end;
    end;
elsif PSTATE.EL == EL2 then
    if !AArch64_CanTrapDC(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
        ExecuteAsNOP();
    else
        if AArch64_TreatDCAsNOP(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
            ExecuteAsNOP();
        else
            AArch64_DC(X{64}(t), CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP);
        end;
    end;
elsif PSTATE.EL == EL3 then
    if AArch64_TreatDCAsNOP(CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP) then
        ExecuteAsNOP();
    else
        AArch64_DC(X{64}(t), CacheType_Tag, CacheOp_Clean, CacheOpScope_PoDP);
    end;
end;
